  //   => C0 + n**4 - 2*n**3 + n**2
  it.todo("rsolve_poly([-1, 1], 4*n**3, n)");
  it("bernoulli(4, n)", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(fn('bernoulli', [rational(4), n]))).toBe('n**4 - 2*n**3 + n**2 - 1/30');
  });
  it("rsolve(f, y(n))", () => {
    const n = new Sym('n');
    expect(sympyStr(rsolve(add(mul(add(-1, n), (SymFunction('y'))(add(2, n))), mul(-1, add(-2, pow(n, 2), mul(3, n)), (SymFunction('y'))(add(1, n))), mul(2, n, add(1, n), (SymFunction('y'))(n))), (SymFunction('y'))(n)))).toBe('2**n*C0 + C1*factorial(n)');
  });
  it("rsolve(f, y(n), {y(0):0, y(1):3})", () => {
    const n = new Sym('n');
    expect(sympyStr(rsolve(add(mul(add(-1, n), (SymFunction('y'))(add(2, n))), mul(-1, add(-2, pow(n, 2), mul(3, n)), (SymFunction('y'))(add(1, n))), mul(2, n, add(1, n), (SymFunction('y'))(n))), (SymFunction('y'))(n), [[(SymFunction('y'))(rational(0)), rational(0)], [(SymFunction('y'))(rational(1)), rational(3)]]))).toBe('3*2**n - 3*factorial(n)');
  });
