  // the arguments do not type-check against the public API
  //   rsolve_hyper([-1, 1], 1 + x, x)
  //   => C0 + x*(x + 1)/2
  it.todo("rsolve_hyper([-1, 1], 1 + x, x)");
  // the arguments do not type-check against the public API
  //   rsolve_poly([-1, 1], 4*n**3, n)
  //   => C0 + n**4 - 2*n**3 + n**2
  it.todo("rsolve_poly([-1, 1], 4*n**3, n) (2)");
